class WorkerSignals(QtCore.QObject):
    """
    Defines the signals available from a running worker thread.

    Supported signals are:
    * finished - no data
    * error - tuple with exctype, value, traceback.format_exc()
    * result - object/any type - data returned from processing
    * progress - int as indication of progress
    """

    finished = QtCore.Signal()
    error = QtCore.Signal(tuple)
    result = QtCore.Signal(object)
    progress = QtCore.Signal(int)


class Worker(QtCore.QRunnable):
    """
    Worker thread

    Inherits from QRunnable to handler worker thread setup, signals and wrap-up.
    """

    def __init__(self, func: Callable, *args: Any, **kwargs: Any) -> None:
        """
        :param func: The function callback to run on worker thread
        :param args: Function positional arguments
        :param kwargs: Function keyword arguments
        """
        super().__init__()
        self.func = func
        self.args = args
        self.kwargs = kwargs
        self.signals = WorkerSignals()
        self.kwargs["progress_callback"] = self.signals.progress

    @QtCore.Slot()
    def run(self):
        """Initialise the runner function with passed args, kwargs."""
        try:
            result = self.func(*self.args, **self.kwargs)
        except Exception:
            exctype, value = sys.exc_info()[:2]
            self.signals.error.emit((exctype, value, traceback.format_exc()))
        else:
            self.signals.result.emit(result)
        finally:
            self.signals.finished.emit()


class LogCollector(QMainWindow):
    """Main windows of LogCollector"""

    def __init__(self, cli_args: Namespace) -> None:
        """
        Simple initialization.

        :param cli_args: Parameters from CLI
        """
        super().__init__(flags=QtCore.Qt.Window)
        uic.loadUi(f"{path.dirname(path.abspath(__file__))}/ui/mainwindow.ui", self)
        self.threadpool = QtCore.QThreadPool.globalInstance()
        global logger
        logger = get_net_logger(SERVER_HOST, LOGGER_PORT, name=f"{self.__class__.__name__}")
        logger.debug(f"QThreadPool with {self.threadpool.maxThreadCount()} thread(s)")
        logger.debug("Env. variable QT_API: {}".format(environ.get("QT_API", "not set")))
        run_tcp_server()
        self.taf_tl_config: TestLine = None
        self.vm_hosts: dict[str, vm_host] = {}
        self.auto_save = False
        self.plugins: dict[str, bool] = {}
        self.log_dir_path = ""
        self.plugins_logs_path = ""
        self.conf_file = ""
        self.simulators_state: dict[str, bool] = defaultdict(bool)
        self.init_menu_bar()
        self.init_mainscreen()
        self.cb_report_bts_info.toggled.connect(self.cb_bts_info_toggled)
        self.tw_main.setTabEnabled(self._get_tab_index("emss"), True)
        self.init_emss()
        self.init_final_report()
        self.init_epc()
        self.init_swconfig()
        self.init_syslog()
        if cli_args.autodetect:
            self.detect_clicked()
        self.init_tti_trace()
        self.init_wireshark()
        self.init_ue_sim()
        self.init_bip()
        self.init_emil()
        self._set_icons()
        yamlfile = path.join(path.dirname(__file__), "..", "default.yml")
        if cli_args.yamlfile:
            yamlfile = cli_args.yamlfile
        self._apply_gui_configuration(yamlfile)
        self.le_store_edited()
        self.cb_emil.setChecked(True)
        self.show()
        create_dir(self.le_store.text())

