    def _save_emil_message_filters(self, vm_no: int) -> None:
        emil_data = self._get_full_emil_data_from_gui(vm_no)
        save_emil_data_to_file(emil_data, self.get_custom_emil_profiles_location(vm_no))
        self.refresh_emil_message_filters(vm_no)

    @staticmethod
    def get_custom_emil_profiles_location(vm_no: int) -> Path:
        import inspect

        from ta_logcollector import settings

        settings_location = Path(inspect.getfile(settings))
        logger.debug(f"Settings location: {settings_location}")
        custom_emil_profiles_location = settings_location.with_name(f"{CUSTOM_EMIL_PROFILES}_{vm_no}.json")
        logger.info(f"Custom Emil profiles location: {custom_emil_profiles_location}")
        return custom_emil_profiles_location

    def _get_full_emil_data_from_gui(self, vm_no: int) -> dict[str, dict[str, list[str]]]:
        lw_emil_monitoring_profiles = getattr(self, f"lw_emil_monitoring_profiles_{vm_no}")
        current_row = lw_emil_monitoring_profiles.currentRow()
        emil_data = {}
        for profile in self._get_all_available_emil_profiles(vm_no):
            row_for_profile = lw_emil_monitoring_profiles.findItems(profile, QtCore.Qt.MatchContains)[0]
            lw_emil_monitoring_profiles.setCurrentItem(row_for_profile)
            emil_data[profile] = {
                "Message filter": self._get_emil_msg_filters(vm_no),
                "Heavy Load Messages": self._get_emil_heavy_load_msg_filters(vm_no),
            }
            logger.warning(f"Row for profile: {row_for_profile.text() = }")
        lw_emil_monitoring_profiles.setCurrentRow(current_row)
        return emil_data

    def _get_all_available_emil_profiles(self, vm_no: int) -> list[str]:
        lw_emil_monitoring_profiles = getattr(self, f"lw_emil_monitoring_profiles_{vm_no}")
        return [profile.text() for profile in lw_emil_monitoring_profiles.findItems("", QtCore.Qt.MatchContains)]

    def _get_emil_msg_filters(self, vm_no: int) -> list[str]:
        pte_emil_msg_filters = getattr(self, f"pte_emil_msg_filters_{vm_no}")
        return pte_emil_msg_filters.toPlainText().split("\n")

    def _get_emil_heavy_load_msg_filters(self, vm_no: int) -> list[str]:
        pte_emil_heavy_load_msg_filters = getattr(self, f"pte_emil_heavy_load_msg_filters_{vm_no}")
        return pte_emil_heavy_load_msg_filters.toPlainText().split("\n")

    def _restore_default_emil_message_filters(self, vm_no: int):
        custom_emil_profiles_location = self.get_custom_emil_profiles_location(vm_no)
        custom_emil_profiles_location.unlink(missing_ok=True)
        self.refresh_emil_message_filters(vm_no)

    def _make_emil_tabs_editable(self, emil_edit_checkbox, vm_no):
        check_status = emil_edit_checkbox.isChecked()
        getattr(self, f"pte_emil_msg_filters_{vm_no}").setReadOnly(not check_status)
        getattr(self, f"pte_emil_heavy_load_msg_filters_{vm_no}").setReadOnly(not check_status)

    def reload_emil_profiles(self):
        """Read and load emil profiles from file to GUI"""
        for vm_no in range(1, MAX_SUPPORTED_VMs + 1):
            lw_emil_monitoring_profiles = getattr(self, f"lw_emil_monitoring_profiles_{vm_no}")
            current_row = lw_emil_monitoring_profiles.currentRow()
            try:
                emil_profiles = reversed(PROFILES.keys()) if is_5g(vm_no, self.taf_tl_config) else PROFILES.keys()
            except ValueError:
                emil_profiles = PROFILES.keys()
            logger.debug("Update {} with {}".format(f"lw_emil_monitoring_profiles_{vm_no}", emil_profiles))
            lw_emil_monitoring_profiles.clear()
            lw_emil_monitoring_profiles.addItems(emil_profiles)
            lw_emil_monitoring_profiles.setCurrentRow(current_row)

    def refresh_emil_message_filters(self, vm_no: int):
        message_filters, heavy_load_message_filters = self._get_emil_msgs_based_on_profiles(vm_no)
        self._fill_emil_msg_filters(vm_no, message_filters, heavy_load_message_filters)

    def _fill_emil_msg_filters(
        self, vm_no: int, message_filters: list[str], heavy_load_message_filters: list[str]
    ) -> None:
        pte_emil_msg_filters = getattr(self, f"pte_emil_msg_filters_{vm_no}")
        pte_emil_heavy_load_msg_filters = getattr(self, f"pte_emil_heavy_load_msg_filters_{vm_no}")
        pte_emil_msg_filters.clear()
        pte_emil_heavy_load_msg_filters.clear()
        pte_emil_msg_filters.setPlainText(
            "\n".join(
                message_filters
                or [
                    "No message found or no profile has been selected. This is most likely an error. Please raise jira."
                ]
            )
        )
        pte_emil_heavy_load_msg_filters.setPlainText("\n".join(heavy_load_message_filters))

    def _get_emil_msgs_based_on_profiles(self, vm_no: int) -> tuple[list[str], list[str]]:
        from ta_logcollector.utils.emil import merge_hex_lists

        selected_profiles = self._get_selected_emil_profiles(vm_no)
        message_filters = set()
        heavy_load_message_filters = set()
        custom_emil_profile_location = self.get_custom_emil_profiles_location(vm_no)
        profiles = (
            get_emil_data_from_file(custom_emil_profile_location) if custom_emil_profile_location.exists() else PROFILES
        )
        for profile_name in selected_profiles:
            profile_data = profiles.get(profile_name, {})
            message_filters |= set(profile_data.get("Message filter", set()))
            heavy_load_message_filters |= set(profile_data.get("Heavy Load Messages", set()))
        message_filters = merge_hex_lists(sorted(message_filters))
        return message_filters, sorted(heavy_load_message_filters, key=lambda msg: msg.split(" #")[0])

    def _get_selected_emil_profiles(self, vm_no: int) -> list[str]:
        lw_emil_monitoring_profiles = getattr(self, f"lw_emil_monitoring_profiles_{vm_no}")
        selected_profiles = [
            selected_profile.text() for selected_profile in lw_emil_monitoring_profiles.selectedItems()
        ]
        return selected_profiles

