    def build_final_report(self, only_active: bool = True) -> dict[str, bool]:
        """
        Build correct final_report configuration as dict with option selected.

        :param only_active:
        :return: full final_report dict configuration
        """
        final_report = {
            checkbox.objectName().split("cb_report_")[1]: checkbox.isChecked()
            for checkbox in self.gb_final_report.children()
            if isinstance(checkbox, QCheckBox)
        }
        if only_active:
            final_report = {option: active for option, active in final_report.items() if active}
        final_report["active"] = self.plugins["final_report"]
        return final_report

