    # <=><=><=><=><=><=><=><=><=><=><=><=> syslog <=><=><=><=><=><=><=><=><=><=><=><=>
    def init_syslog(self):
        """Configure syslog tab widget"""
        for vm in vms_list:
            for widget in ["cb_syslog_enb_{}", "cb_syslog_uesim_{}"]:
                getattr(self, widget.format(vm)).toggled.connect(self.trigger_autosave)
            for widget in ["le_syslog_enb_{}", "le_syslog_uesim_{}"]:
                getattr(self, widget.format(vm)).textChanged.connect(self.trigger_autosave)
            self._enable_syslog_group(vm, False)

    def build_syslog(self) -> dict:
        """
        Build correct syslog configuration as dict of VMs dicts.

        :return: full syslog dict configuration
        """
        syslog = {"active": self.plugins["syslog"], "compress": self.cb_syslog_compress.isChecked()}
        for vm in vms_list:
            vm_dict = {
                key: literal_eval(str(sub(r"[\[\]\s\'\"]", "", getattr(self, widget.format(vm)).text()).split(",")))
                for key, widget in {"enb_ip": "le_syslog_enb_{}", "iphy_ip": "le_syslog_uesim_{}"}.items()
            }
            vm_dict.update(
                {
                    key: getattr(self, widget.format(vm)).isChecked()
                    for key, widget in {"enb": "cb_syslog_enb_{}", "iphy": "cb_syslog_uesim_{}"}.items()
                }
            )
            syslog[vm] = vm_dict
        return syslog

    def _enable_syslog_group(self, vm: str, state: bool) -> None:
        getattr(self, f"gb_syslog_{vm}").setEnabled(state)

    def _enable_emss_bts_checkbox(self, vm: str, state: bool) -> None:
        getattr(self, f"cb_emss_bts_{vm}").setChecked(state)

    # <=><=><=><=><=><=><=><=><=><=><=><=> tti <=><=><=><=><=><=><=><=><=><=><=><=>
    def init_tti_trace(self) -> None:
        """Configure tti trace tab widget"""
        self.pb_tti_detect.clicked.connect(self.update_tti_box)

    def update_tti_box(self):
        not_connected: list[str] = []
        for vm_id, _ in enumerate(self.vm_hosts, start=1):
            if is_5g(vm_id, self.taf_tl_config):
                self.update_tti_box_5g(vm_id)
            elif is_4g(vm_id, self.taf_tl_config):
                self.update_tti_box_4g(vm_id)
            else:
                not_connected.append(f"{vm_id}")
        if not_connected:
            self._update_lc_statusbar(f"VMs {', '.join(not_connected)} are not connected to any eNB")
        else:
            self._update_lc_statusbar("Detected cells for all connected VMs")

    def update_tti_box_5g(self, vm_id: int):
        """ " Checks all configured cells on gNB and lists them in the tti box"""
        self._set_icons(button="pb_tti_detect", icon_name="fa5s.spinner", color="green", spin=True)
        done_event = Event()
        self.run_in_background(
            job=partial(self._fake_progress, total_time=25, done_event=done_event),
            signal_handlers={"progress": self._progress_by_abs_value},
        )
        self.run_in_background(
            job=partial(self._get_gnb_cells_and_fill_tti_box, vm_id=vm_id, done_event=done_event),
            signal_handlers={"finished": self._set_gnb_cells_for_tti_completed},
        )

    def _get_gnb_cells_and_fill_tti_box(self, vm_id: int, done_event: Event, progress_callback: QtCore.Signal) -> None:
        vm_name = f"vm{vm_id}"
        progress_callback.emit(0)
        getattr(self, f"tw_tti_{vm_id}").clear()
        logger.debug(f"[TTI] Will fetch gNB and cells info from {vm_name}: {self.vm_hosts[vm_name]}")
        self._fill_up_tti_cells_info_box(vm_name)
        logger.debug(f"[TTI] Done fetching cells for gNB on {vm_name}: {self.vm_hosts[vm_name]}")
        done_event.set()

    def _fill_up_tti_cells_info_box(self, vm_name: str) -> None:
        try:
            gnb_id, cells_info = self._get_gnb_cells_info(vm_name)
            self._fill_up_tti_cells_info(vm_name, gnb_id, cells_info)
        except Exception as e:
            logger.exception(e)
            self._fill_up_tti_cells_box_with_error_info(
                vm_name,
                f"Couldn't connect to admin(WebEM). Check connectivity on vm{vm_name} with address: {BTS_TRANSPORT_IP}",
            )

    def _create_top_level_item(self, text: str, *flags: QtCore.Qt.ItemFlags) -> QTreeWidgetItem:
        flags_sum = 0
        for flag in flags:
            flags_sum |= flag
        top_lvl_item = QTreeWidgetItem([text, "", ""])
        top_lvl_item.setCheckState(0, QtCore.Qt.Unchecked)
        top_lvl_item.setFlags(flags_sum)
        return top_lvl_item

    def _fill_up_tti_cells_box_with_error_info(self, host: str, error_info: str) -> None:
        top_lvl_item = self._create_top_level_item(f"{host}: {error_info}", QtCore.Qt.ItemIsAutoTristate)
        top_lvl_item.setForeground(0, QColor("red"))
        self.tree_tti_trace.addTopLevelItem(top_lvl_item)
        self.tree_tti_trace.expandItem(top_lvl_item)
        self.tree_tti_trace.header().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)

    def _fill_up_tti_cells_info(self, vm_name: str, gnb_id: int, cells_info: list[dict]) -> None:
        top_lvl_item = self._cells_get_top_lvl_tree_item_for_tti_box(gnb_id)
        for cell in cells_info:
            l1_child = self._cells_detect_child_tree_item_for_tti(cell)
            top_lvl_item.addChild(l1_child)
        vm_id = vm_name.strip("vm")
        tw_tti = getattr(self, f"tw_tti_{vm_id}")
        tw_tti.addTopLevelItem(top_lvl_item)
        tw_tti.expandItem(top_lvl_item)
        tw_tti.header().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)

    def _set_gnb_cells_for_tti_completed(self):
        self._set_icons(button="pb_tti_detect", icon_name="fa5s.check", color="green", spin=False)

    def _cells_get_top_lvl_tree_item_for_tti_box(self, gnb_id: int) -> QTreeWidgetItem:
        top_lvl_item = self._create_top_level_item(
            f"gNB-{gnb_id}",
            QtCore.Qt.ItemIsAutoTristate,
            QtCore.Qt.ItemIsEnabled,
            QtCore.Qt.ItemIsUserCheckable,
        )
        return top_lvl_item

    def update_tti_box_4g(self, vm_id: int):
        self._set_icons(button="pb_tti_detect", icon_name="fa5s.spinner", color="green", spin=True)
        done_event = Event()
        self.run_in_background(
            job=partial(self._fake_progress, total_time=10, done_event=done_event),
            signal_handlers={"progress": self._progress_by_abs_value},
        )
        self.run_in_background(
            job=partial(self._detect_cell_map, vm_id=vm_id, done_event=done_event),
            signal_handlers={"finished": self._detect_cell_map_completed},
        )

    @staticmethod
    def _cells_detect_child_tree_item_for_tti(cell_params: dict[str, Any]) -> QTreeWidgetItem:
        l1_child = QTreeWidgetItem(
            ["Cell {}".format(cell_params["id"]), cell_params["status"], "PCI: {}".format(cell_params["phy_cell_id"])]
        )
        l1_child.setCheckState(0, QtCore.Qt.Checked)
        l1_child.setFlags(QtCore.Qt.ItemIsAutoTristate | QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsUserCheckable)
        l1_child.setTextAlignment(1, QtCore.Qt.AlignHCenter)
        return l1_child

    def _detect_cell_map(self, vm_id: int, done_event: Event, progress_callback: QtCore.Signal) -> None:
        progress_callback.emit(0)
        tasks_list = []
        getattr(self, f"tw_tti_{vm_id}").clear()
        host_name = f"vm{vm_id}"
        logger.debug(f"[TTI] Will fetch cell-mapping for {host_name}")
        task = Task(
            CellMapping(host=ENB_IPs[host_name], logger=logger),
            fn_callback=partial(self._fill_up_cell_mapping_structure, vm_id),
        )
        tasks_list.append(task)
        execute_in_parallel(tasks_list)
        logger.debug("[TTI] Done fetching cell-mapping for all requested vms.")
        done_event.set()

    def _detect_cell_map_completed(self):
        self._set_icons(button="pb_tti_detect", icon_name="fa5s.check", color="green", spin=False)

    def _fill_up_cell_mapping_structure(self, vm_id: int, future: Future) -> None:
        host_name = f"vm{vm_id}"
        enb_info = future.result()
        cell_map = enb_info.cell_mapping
        master_nid = enb_info.master_nid

        vm_cell, status = 0, 1
        tw_tti = getattr(self, f"tw_tti_{vm_id}")
        top_lvl_item = self._cellmap_top_lvl_tree_item(host_name, master_nid, vm_cell, tw_tti)
        for cell_params in cell_map:
            l1_child = self._cellmap_child_tree_item_vmcell_column0(cell_params, vm_cell)
            l1_child = self._cellmap_child_tree_item_status_column1(cell_params, l1_child, status)
            self._cellmap_child_tree_item_direction_column2(
                cell_params, host_name, top_lvl_item, l1_child, vm_cell, tw_tti
            )

        tw_tti.addTopLevelItem(top_lvl_item)
        tw_tti.expandItem(top_lvl_item)
        tw_tti.header().setSectionResizeMode(vm_cell, QHeaderView.ResizeMode.ResizeToContents)
        tw_tti.header().setSectionResizeMode(status, QHeaderView.ResizeMode.ResizeToContents)

    @staticmethod
    def _cellmap_top_lvl_tree_item(
        host_name: str, master_nid: str, vm_cell: int, tw_tti: QTreeWidgetItem
    ) -> QTreeWidgetItem:
        for idx in range(tw_tti.topLevelItemCount()):
            item = tw_tti.topLevelItem(idx)
            if item.text(vm_cell) == host_name:
                tw_tti.takeTopLevelItem(idx)
            idx += 1
        top_lvl_item = QTreeWidgetItem([host_name, "", f"master_nid: {master_nid}"])
        top_lvl_item.setCheckState(vm_cell, QtCore.Qt.Unchecked)
        top_lvl_item.setFlags(QtCore.Qt.ItemIsAutoTristate | QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsUserCheckable)
        return top_lvl_item

    @staticmethod
    def _cellmap_child_tree_item_vmcell_column0(
        cell_params: dict[str, Union[int, str]], vm_cell: int
    ) -> QTreeWidgetItem:
        l1_child = QTreeWidgetItem(
            [
                "cell ID {}".format(cell_params["lcr"]),
                "",
                "lnCel: {} lcr: {} pci: {} eutraCelId: {} MACULTTI: {} MACDLTTI: {}".format(
                    cell_params["lnCel"],
                    cell_params["lcr"],
                    cell_params["pci"],
                    cell_params["eutraCelId"],
                    hex(cell_params["MACULTTI"]),
                    hex(cell_params["MACDLTTI"]),
                ),
            ]
        )
        l1_child.setCheckState(vm_cell, QtCore.Qt.Unchecked)
        l1_child.setFlags(QtCore.Qt.ItemIsAutoTristate | QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsUserCheckable)
        return l1_child

    def _cellmap_child_tree_item_status_column1(
        self, cell_params: dict[str, Union[int, str]], l1_child: QTreeWidgetItem, status: int
    ) -> QTreeWidgetItem:
        l1_child.setText(status, "OnAir")
        l1_child.setIcon(status, qtawesome.icon("fa5s.check", color="green"))
        if not (cell_params["MACULTTI"] or cell_params["MACDLTTI"]):
            l1_child.setFlags(QtCore.Qt.NoItemFlags)
            l1_child.setIcon(status, qtawesome.icon("fa5s.times", color="red"))
        return l1_child

    def _cellmap_child_tree_item_direction_column2(
        self,
        cell_params: dict[str, Union[int, str]],
        host_name: str,
        top_lvl_item: QTreeWidgetItem,
        l1_child: QTreeWidgetItem,
        vm_cell: int,
        tw_tti: QTreeWidgetItem,
    ) -> None:
        dirs = {"UL": "Uplink", "DL": "Downlink"}
        if cell_is_nbiot(cell_params):
            del dirs["UL"]
        for direction, desc in dirs.items():
            l1_dir = QTreeWidgetItem([direction, "", desc])
            self._cross_check_cellmap_with_loaded_config(l1_dir, int(host_name[-1]), cell_params["lnCel"], direction)
            if not int(l1_child.flags()):
                l1_dir.setCheckState(vm_cell, QtCore.Qt.Unchecked)
                l1_dir.setFlags(QtCore.Qt.NoItemFlags)
            l1_child.addChild(l1_dir)
        top_lvl_item.addChild(l1_child)
        tw_tti.expandItem(l1_child)

    def _cross_check_cellmap_with_loaded_config(
        self, qtwi: QTreeWidgetItem, enb: int, cell: int, direction: str
    ) -> None:
        if not self.config.get("tti_trace", {}).get("cells", {}) or direction in self.config.get("tti_trace", {}).get(
            "cells", {}
        ).get(enb, {}).get(cell, "0"):
            qtwi.setCheckState(0, QtCore.Qt.Checked)
        else:
            qtwi.setCheckState(0, QtCore.Qt.Unchecked)

    def build_tti_trace(self, vm_id: int) -> dict[str, Any]:
        if is_5g(vm_id, self.taf_tl_config):
            return self.build_tti_trace_for_gnb(vm_id)
        elif is_4g(vm_id, self.taf_tl_config):
            return self.build_tti_trace_for_enb(vm_id)
        else:
            self._update_lc_statusbar(
                f"Cannot detect technology on {vm_id}. TTI will not work there. " f"Please check BTS connectivity."
            )

    def build_tti_trace_for_gnb(self, vm_id: int) -> dict[str, Any]:
        """
        Build correct TTI trace configuration
        :return: tti configuration, e.g. {'active': True, 'bts_type': 'gnb', 'gnb': 1, 'cells': [50, 51]}
        """
        cell_column = 0
        tti_trace = {"active": self.plugins["tti_trace"], "bts_type": "gnb", "gnb": None}
        cells = []
        tw_tti = getattr(self, f"tw_tti_{vm_id}")
        for cell in tw_tti.findItems("Cell.*", QtCore.Qt.MatchRegExp | QtCore.Qt.MatchRecursive, 0):
            if cell.checkState(cell_column) == QtCore.Qt.CheckState.Checked:
                tti_trace["gnb"] = self._get_gnb_id_for_selected_cell(cell=cell)
                pci = self._get_pci_for_selected_cell(cell=cell)
                cells.append(pci)
        tti_trace["cells"] = cells
        return tti_trace

    @staticmethod
    def _get_gnb_id_for_selected_cell(cell: QTreeWidgetItem) -> int:
        """
        Parses gnb id from the tti tree item based on the given cell.
        cell: information about cell included in QTreeWidgetItem
        e.g:
            tti tree (QTreeWidget):
                | vm1: gNB-1:   |           |           |   <- parent item
                |    Cell 1     |  enabled  |  PCI: 50  |   <- cell item
                |    Cell 2     |  enabled  |  PCI: 51  |   <- cell item
        """
        parent_item = cell.parent()
        gnb = parent_item.text(0).split()[-1]
        gnb_id = int(gnb.split("-")[-1])
        return gnb_id

    @staticmethod
    def _get_pci_for_selected_cell(cell: QTreeWidgetItem) -> int:
        """
        Parses physical cell id from the tti tree item based on the given cell.
        cell: information about cell included in QTreeWidgetItem
        e.g:
            cell (QTreeWidgetItem):
              |  Cell 1  |  enabled  |  PCI: 50  |
        """
        pci_column_id = 2
        pci = int(cell.text(pci_column_id).split()[-1])
        return pci

    def build_tti_trace_for_enb(self, vm_id: int) -> dict:
        """
        Build correct tti_trace configuration as dict of VMs dicts.

        It converts from:
         {'vm1': {'1': 'UL'},
          'vm2': {'2': 'DL', '3': 'DL'},
          'vm3': {},
          'vm4': {'1': 'ULDL'}}
        to:
        {'cells': {1: {1: 'UL'},
                   2: {2: 'DL', 3: 'DL'},
                   4: {1: 'ULDL'}},
         'bts_type': 'enb'}

        Due to nature of tti_trace plugin all heavy lifting is done by vm1 only.
        So, whole configuration in push to vm1 only:
        tti_cfg = {'cells': {'1': {'1': 'DL', '2': 'UL', '3': 'ULDL'},
                             '2': {'1': 'UL', '2': 'UL', '3': 'ULDL'}}
                   'bts_type': 'enb'}
        where:
        tti_cfg = {'cells': {<eNb_id>: {<cell_id>: <direction>}}

        :return: full tti_trace dict configuration
        """
        vm_cell, info = 0, 2
        tti_trace = {"active": self.plugins["tti_trace"], "bts_type": "enb"}
        vms: dict[str, dict[str, str]] = {vm: {} for vm in vms_list}
        tw_tti = getattr(self, f"tw_tti_{vm_id}")
        for item in tw_tti.findItems("DL|UL", QtCore.Qt.MatchRegExp | QtCore.Qt.MatchRecursive, vm_cell):
            vm = item.parent().parent().text(vm_cell)
            if item.checkState(vm_cell) == QtCore.Qt.CheckState.Checked:
                lncel = search(r"lnCel:\s([0-9]+)", item.parent().text(info)).group(1)
                vms[vm][lncel] = vms[vm].get(lncel, "")
                vms[vm][lncel] += item.text(vm_cell)
        tti_trace["cells"] = {
            int(vm[-1]): {int(cell): direction for cell, direction in cells_dict.items()}
            for vm, cells_dict in vms.items()
            if cells_dict
        }
        return tti_trace

    # <=><=><=><=><=><=><=><=><=><=><=><=> ue_sim <=><=><=><=><=><=><=><=><=><=><=><=>
    def init_ue_sim(self):
        """Configure ue_sim tab widget"""
        for idx, sim in enumerate(["iphy", "cus", "airphone"]):
            sim_checkbox = getattr(self, f"cb_{sim}")
            sim_checkbox.toggled.connect(self.trigger_autosave)
            sim_checkbox.toggled.connect(partial(self.cb_sim_toggled, idx))

        self.le_epc_ip2.textChanged.connect(self.trigger_autosave)
        self.le_epc_ip2.textChanged.connect(partial(LogCollector._egate_connection_changed_insync, self.le_epc_ip))
        self.le_epc_port2.textChanged.connect(self.trigger_autosave)
        self.le_epc_port2.textChanged.connect(partial(LogCollector._egate_connection_changed_insync, self.le_epc_port))
        self.cb_iphy_sosreport.toggled.connect(self.trigger_autosave)
        for proxy in iphy_proxy_list:
            getattr(self, f"cb_iphy_{proxy}").toggled.connect(self.trigger_autosave)

        self.le_cus_executor_ip.textChanged.connect(self.trigger_autosave)
        self.le_cus_executor_port.textChanged.connect(self.trigger_autosave)
        self.cb_cus_sosreport.toggled.connect(self.trigger_autosave)

        self.cb_airphone_sosreport.toggled.connect(self.trigger_autosave)

    def _detect_and_check_ue_simulators(self):
        for simulator, sim_exists in check_tl_config_for_ue_sim(self.taf_tl_config):
            logger.debug(f"simulator {simulator} exists = {sim_exists}")
            state = sim_exists and self.config["ue_sim"][simulator]["active"]
            getattr(self, f"cb_{simulator}").setChecked(state)
            self.simulators_state[simulator] = state

    def build_ue_sim(self, only_active: bool = True) -> dict[str, Any]:
        ue_sim = {"active": True}
        if self.cb_iphy.isChecked():
            ue_sim["iphy"] = self._build_iphy(only_active)
        if self.cb_cus.isChecked():
            ue_sim["cus"] = self._build_cus()
        if self.cb_airphone.isChecked():
            ue_sim["airphone"] = self._build_airphone()
        return ue_sim

    def _build_iphy(self, only_active):
        proxies = {name: getattr(self, f"cb_iphy_{name}").isChecked() for name in iphy_proxy_list}
        if only_active:
            proxies = {name: active for name, active in proxies.items() if active}
        iphy = {
            "active": True,
            "egate_host": self.le_epc_ip2.text(),
            "egate_port": int(self.le_epc_port2.text()),
            "sosreport": self.cb_iphy_sosreport.isChecked(),
            "proxy": proxies,
        }
        return iphy

    def _build_cus(self):
        return {
            "active": True,
            "executor_ip": self.le_cus_executor_ip.text(),
            "executor_port": int(self.le_cus_executor_port.text()),
            "sosreport": self.cb_cus_sosreport.isChecked(),
        }

    def _build_airphone(self):
        raise NotImplementedError

    def cb_sim_toggled(self, idx: int, requested_state: bool) -> None:
        """
        Switch to sim internal tab when simulator checkbox is toggled.

        :param idx:
        :param requested_state:
        """
        if requested_state:
            self.tw_sims.setCurrentIndex(idx)

    # <=><=><=><=><=><=><=><=><=><=><=><=> wireshark <=><=><=><=><=><=><=><=><=><=><=><=>
    def init_wireshark(self):
        """Configure syslog tab widget"""
        for proto in wireshark_protocols:
            getattr(self, f"cb_wireshark_{proto}").toggled.connect(self.trigger_autosave)
        for col_type in ["vm", "enb"]:
            attr = getattr(self, f"rb_wireshark_{col_type}")
            attr.toggled.connect(self.trigger_autosave)
            attr.toggled.connect(self.wireshark_toggled)

    def wireshark_toggled(self):
        if self.rb_wireshark_vm.isChecked():
            getattr(self, "cb_wireshark_sctp").setChecked(False)
        if self.rb_wireshark_enb.isChecked():
            getattr(self, "cb_wireshark_sctp").setChecked(True)
            getattr(self, "cb_wireshark_rrc").setChecked(False)
            getattr(self, "cb_wireshark_x2").setChecked(False)
            getattr(self, "cb_wireshark_s1").setChecked(False)
            getattr(self, "cb_wireshark_m3").setChecked(False)

