    def init_bip(self):
        """Configure BIP trace tab widget"""
        self.pb_gnbbip_detect.clicked.connect(self.detect_gnb_cells_and_fill_gnbbip_box)
        self.rb_gnbbip_l1l2.toggled.connect(self.trigger_autosave)
        self.rb_gnbbip_l2hil2lo.toggled.connect(self.trigger_autosave)
        self.rb_gnbbip_allcells.toggled.connect(self.trigger_autosave)
        self.rb_gnbbip_allcells.toggled.connect(self.specific_cells_toggled)
        self.rb_gnbbip_specific_cells.toggled.connect(self.trigger_autosave)
