    def specific_cells_toggled(self):
        if self.rb_gnbbip_allcells.isChecked():
            self.tree_gnbbip_detect.setEnabled(False)
        else:
            self.tree_gnbbip_detect.setEnabled(True)

    def detect_gnb_cells_and_fill_gnbbip_box(self):
        self._set_icons(button="pb_gnbbip_detect", icon_name="fa5s.spinner", color="green", spin=True)
        self.rb_gnbbip_allcells.setChecked(False)
        self.rb_gnbbip_specific_cells.setChecked(True)
        done_event = Event()
        self.run_in_background(
            job=partial(self._fake_progress, total_time=25, done_event=done_event),
            signal_handlers={"progress": self._progress_by_abs_value},
        )
        self.run_in_background(
            job=partial(self._detect_gnb_cells_and_fill_gnbbip_box, done_event=done_event),
            signal_handlers={"finished": self._detect_gnb_cells_completed},
        )

    def _detect_gnb_cells_and_fill_gnbbip_box(self, done_event: Event, progress_callback: QtCore.Signal) -> None:
        progress_callback.emit(0)
        self.tree_gnbbip_detect.clear()
        tasks_list = []
        for host_name, host_data in self.vm_hosts.items():
            logger.debug(f"[BIP] Will fetch gNB and cells info from {host_name}")
            tasks_list.append(Task(self._fill_up_gnb_cells_info_box, host_name, host_data.addr))
        execute_in_parallel(tasks_list)
        logger.debug("[BIP] Done fetching cells for all gNB")
        done_event.set()

    def _fill_up_gnb_cells_info_box(self, host: str, host_addr: str) -> None:
        try:
            gnb_id, cells_info = self._get_gnb_cells_info(alias=host, host_addr=host_addr)
        except Exception as e:
            logger.exception(e)
            self._fill_up_gnb_cells_box_with_error_info(
                host,
                f"Couldn't connect to admin(WebEM). Check connectivity on {host} with address: {BTS_HOST_IP}",
            )
        else:
            self._fill_up_gnb_cells_info(host, gnb_id, cells_info)

    def _fill_up_gnb_cells_box_with_error_info(self, host: str, error_info: str) -> None:
        top_lvl_item = self._create_top_level_item(f"{host}: {error_info}", QtCore.Qt.ItemIsAutoTristate)
        top_lvl_item.setForeground(0, QColor("red"))
        self.tree_gnbbip_detect.addTopLevelItem(top_lvl_item)
        self.tree_gnbbip_detect.expandItem(top_lvl_item)
        self.tree_gnbbip_detect.header().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)

    def _fill_up_gnb_cells_info(self, host: str, gnb_id: int, cells_info: list[dict]) -> None:
        top_lvl_item = self._cells_detect_top_lvl_tree_item(host, gnb_id)
        for cell in cells_info:
            l1_child = self._cells_detect_child_tree_item(cell)
            top_lvl_item.addChild(l1_child)
        self.tree_gnbbip_detect.addTopLevelItem(top_lvl_item)
        self.tree_gnbbip_detect.expandItem(top_lvl_item)
        self.tree_gnbbip_detect.header().setSectionResizeMode(0, QHeaderView.ResizeMode.ResizeToContents)

    def _get_gnb_cells_info(self, vm_name: str) -> tuple[int, list[dict,]]:
        vm_id = int(vm_name.strip("vm")) - 1
        try:
            bts_info = self.taf_tl_config.test_pcs[vm_id].connections[0].device.lmp_connection
        except AttributeError:
            logger.debug("Connections not contains device, trying lmp_connection directly")
            bts_info = self.taf_tl_config.test_pcs[vm_id].connections[0].lmp_connection
        with AdminInterface(
            log_host=SERVER_HOST,
            log_port=LOGGER_PORT,
            alias=vm_name,
            host=bts_info.addr,
            remote_host=self.vm_hosts[vm_name].addr,
        ) as admin:
            gnb_id = admin.get_gnb_id()
            cells = admin.get_cells()
        return gnb_id, cells

    def _cells_detect_top_lvl_tree_item(self, host: str, gnb_id: int) -> QTreeWidgetItem:
        top_lvl_item = self._create_top_level_item(
            f"{host}: gNB-{gnb_id}",
            QtCore.Qt.ItemIsAutoTristate,
            QtCore.Qt.ItemIsEnabled,
            QtCore.Qt.ItemIsUserCheckable,
        )
        return top_lvl_item

    def _cells_detect_child_tree_item(self, cell_params: dict[str, Any]) -> QTreeWidgetItem:
        l1_child = QTreeWidgetItem(
            ["Cell {}".format(cell_params["id"]), str(cell_params["phy_cell_id"]), cell_params["status"]]
        )
        l1_child.setCheckState(0, QtCore.Qt.Checked)
        l1_child.setFlags(QtCore.Qt.ItemIsAutoTristate | QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsUserCheckable)
        l1_child.setTextAlignment(1, QtCore.Qt.AlignHCenter)
        return l1_child

    def _detect_gnb_cells_completed(self):
        self._set_icons(button="pb_gnbbip_detect", icon_name="fa5s.check", color="green", spin=False)

    def build_bip(self) -> dict[str, Any]:
        """
        Build correct BIP configuration for all VMs
        :return: bip configuration, e.g. {'active': True, 'kwargs': {'vm2': {'interface': 'L1-L2', 'phy_cell_ids': [50]}}}
        """
        cell_column, pci_column = 0, 1
        interface = "L1-L2"
        vms = {}
        if self.rb_gnbbip_l2hil2lo.isChecked():
            interface = "L2Hi-L2Lo"
        if self.rb_gnbbip_specific_cells.isChecked():
            for cell in self.tree_gnbbip_detect.findItems(
                "Cell.*", QtCore.Qt.MatchRegExp | QtCore.Qt.MatchRecursive, 0
            ):
                if cell.checkState(cell_column) == QtCore.Qt.CheckState.Checked:
                    vm = cell.parent().text(0).split(":")[0]
                    pci = int(cell.text(pci_column))
                    if vm not in vms:
                        vms[vm] = {"interface": interface, "phy_cell_ids": [pci]}
                    else:
                        vms[vm]["phy_cell_ids"].append(pci)
        else:
            for host in self.vm_hosts:
                vms[host] = {"interface": interface, "phy_cell_ids": []}
        return {"active": self.plugins["bip"], "kwargs": vms}

    # <=><=><=><=><=><=><=><=><=><=><=><=> detect <=><=><=><=><=><=><=><=><=><=><=><=>
    def detect_clicked(self):
        """Detect testline configuration."""
        self.taf_tl_config, _ = get_tl_cfg(logger)
        self._set_icons(button="pb_detect", icon_name="fa5s.spinner", color="green", spin=True)
        self.progress_bar.setValue(0)
        done_event = Event()
        self.run_in_background(
            job=partial(self._fake_progress, total_time=11, done_event=done_event),
            signal_handlers={"progress": self._progress_by_abs_value},
        )

        for index, host in enumerate(self.taf_tl_config.test_pcs, 1):
            ssh_info = host.default_ssh_connection_details
            addr = SERVER_HOST if ssh_info.addr == "127.0.0.1" else ssh_info.addr
            self.vm_hosts[f"vm{index}"] = vm_host(
                addr=addr, usr=ssh_info.username, passwd=ssh_info.password, alive=False
            )
            for field_name in ["addr", "usr", "passwd"]:
                le_widget = getattr(self, f"le_vm{index}_{field_name}")
                le_widget.setText(getattr(self.vm_hosts[f"vm{index}"], field_name))
                cb_widget = getattr(self, f"cb_vm{index}")
                cb_widget.setChecked(True)
        self.run_in_background(
            job=partial(self._detect, done_event=done_event), signal_handlers={"result": self._detect_partly_finished}
        )

    def _detect(
        self, done_event: Event, progress_callback: QtCore.Signal
    ) -> tuple[bool, str, list[lc_info], list[lc_info], str, Event]:  # keep it
        is_new_ver, latest_ver = new_version_exists("ta_logcollector", __version__)
        lc_hosts_info = check_logcollector_version_on_hosts(logger, self.vm_hosts)
        versions_mismatch = [lc_host_info for lc_host_info in lc_hosts_info if lc_host_info.version != __version__]
        logger.debug(f"lc_hosts = {lc_hosts_info}, versions_mismatch = {versions_mismatch}")
        return is_new_ver, latest_ver, lc_hosts_info, versions_mismatch, self.testline_name, done_event

    def _detect_partly_finished(
        self, partly_detect_result: tuple[bool, str, list[lc_info], list[lc_info], str, Event]
    ) -> None:
        is_new_ver, latest_ver, lc_hosts_info, versions_mismatch, tl_name, done_event = partly_detect_result
        self.gb_vms.setTitle(f"Virtual Machines for: {tl_name}")
        if versions_mismatch or is_new_ver:
            mismatches = "".join(
                ["* <b>{}: </b>version<b> {}</b><br>".format(*lc_host_info) for lc_host_info in lc_hosts_info]
            )

            first_line = (
                f"New version available <b>{latest_ver}</b>.<br>"
                if is_new_ver
                else f"You are running version: <b>{__version__}</b>.<br>"
            )
            reply = QMessageBox.question(
                self,
                "Version information",
                "{}"
                "Nodes information:<br><br>"
                "{}"
                "<br>"
                "Please update ta_logcollector to <b>{}</b> on all nodes and restart.<br><br>"
                "Press <b>Close</b> to quit logcollector or <b>Ignore</b> mismatch.".format(
                    first_line, mismatches, latest_ver
                ),
                QMessageBox.Ignore | QMessageBox.Close,
                QMessageBox.Close,
            )
            if reply != QMessageBox.Ignore:
                seppuku(logger)
        else:
            logger.debug("No version missmatch found")
        self._set_icons(button="pb_check_servers", icon_name="fa5s.spinner", color="green", spin=True)
        self._prepare_for_check_servers()
        self._get_servers_state()
        self.run_in_background(
            job=partial(self._detect_continue, done_event=done_event),
            signal_handlers={"error": self._error_during_detect, "result": self._detect_completed},
        )

    def _detect_continue(self, done_event: Event, progress_callback: QtCore.Signal) -> Event:
        ServerStartupManager(self.vm_hosts).start()
        return done_event

    def _detect_completed(self, done_event: Event) -> None:
        done_event = done_event
        if not self.pb_stop.isEnabled() or all([not self.pb_stop.isEnabled(), not self.pb_start.isEnabled()]):
            self.pb_start.setEnabled(True)
        self.pb_tti_detect.setEnabled(True)
        self.pb_gnbbip_detect.setEnabled(True)
        self.pb_check_servers.setEnabled(True)
        self._set_servers_status_after_post_check()
        self._set_icons(button="pb_detect", icon_name="fa5s.check", color="green", spin=False)
        self._set_icons(button="pb_check_servers", icon_name="fa5s.sync", color="blue", spin=False)
        self._update_lc_statusbar("Detect completed")
        done_event.set()

    def check_servers_clicked(self):
        """Handling of check servers push button."""
        self._prepare_for_check_servers()
        done_event = Event()
        self.run_in_background(
            job=partial(self._fake_progress, total_time=6, done_event=done_event),
            signal_handlers={"progress": self._progress_by_abs_value},
        )
        self.run_in_background(
            job=partial(self._check_servers, done_event=done_event),
            signal_handlers={"finished": self._check_servers_completed},
        )

    def _prepare_for_check_servers(self):
        self._update_lc_statusbar("Checking servers...")
        self._set_icons(button="pb_check_servers", icon_name="fa5s.spinner", color="green", spin=True)
        for index in range(1, MAX_SUPPORTED_VMs + 1):
            if getattr(self, f"cb_vm{index}").isChecked():
                self._update_lc_statusbar(f"Check server for VM {index}")
                self.vm_hosts[f"vm{index}"] = vm_host(
                    addr=getattr(self, f"le_vm{index}_addr").text(),
                    usr=getattr(self, f"le_vm{index}_usr").text(),
                    passwd=getattr(self, f"le_vm{index}_passwd").text(),
                    alive=False,
                )
            elif self.vm_hosts.get(f"vm{index}"):
                del self.vm_hosts[f"vm{index}"]

    def _check_servers(self, done_event: Event, progress_callback: QtCore.Signal) -> None:
        progress_callback.emit(0)
        ServerStartupManager(self.vm_hosts).start()
        done_event.set()

    def _set_servers_status_after_post_check(self):
        for vm_number, vmhost in self.vm_hosts.items():
            cb_widget = getattr(self, f"cb_{vm_number}")
            if vmhost.alive:
                cb_widget.setStyleSheet(
                    "QCheckBox {border: 1px solid gray; border-radius: 3px; " "background-color: green; color: white;}"
                )
                self.pb_start.setEnabled(True)
                self.pb_tti_detect.setEnabled(True)
            else:
                cb_widget.setStyleSheet(
                    "QCheckBox {border: 1px solid gray; border-radius: 3px; " "background-color: red; color: white;}"
                )

    def _check_servers_completed(self):
        """Handling of check servers push button."""
        self._set_servers_status_after_post_check()
        self._update_lc_statusbar("Servers were checked")
        self._set_icons(button="pb_check_servers", icon_name="fa5s.sync", color="blue", spin=False)

    def shutdown_servers_clicked(self):
        """Handling of reset servers push button."""
        self._update_lc_statusbar("Servers are shutting down... ")
        self.run_in_background(
            job=partial(self._fake_progress, total_time=1, done_event=Event()),
            signal_handlers={"progress": self._progress_by_abs_value},
        )
        self.run_in_background(job=self._kill_servers, signal_handlers={"finished": self._shutdown_servers_completed})
        kill_lc_servers(hosts=self.vm_hosts)

    def _kill_servers(self, progress_callback: QtCore.Signal) -> None:
        progress_callback.emit(0)
        kill_lc_servers(hosts=self.vm_hosts)

    def _shutdown_servers_completed(self):
        kill_lc_servers(hosts=self.vm_hosts)
        logger.debug(f"Reset hosts: {self.vm_hosts}")
        for index in range(1, MAX_SUPPORTED_VMs + 1):
            if all(
                [
                    getattr(self, f"le_vm{index}_addr").text(),
                    getattr(self, f"le_vm{index}_usr").text(),
                    getattr(self, f"le_vm{index}_passwd").text(),
                ]
            ):
                self.vm_hosts[f"vm{index}"] = vm_host(
                    addr=self.vm_hosts[f"vm{index}"].addr,
                    usr=self.vm_hosts[f"vm{index}"].usr,
                    passwd=self.vm_hosts[f"vm{index}"].passwd,
                    alive=False,
                )
                getattr(self, f"cb_vm{index}").setChecked(False)
                getattr(self, f"cb_vm{index}").setChecked(True)
                getattr(self, f"cb_vm{index}").setStyleSheet(
                    "QCheckBox {border: 1px solid gray; border-radius: 3px; " "background-color: red; color: white;}"
                )
        self._update_lc_statusbar("Servers were reset")
        logger.debug(f"hosts after reset: {self.vm_hosts}")

    def _get_servers_state(self):
        states = []
        for vm_data in self.vm_hosts.values():
            state = send_get_state_request(logger, vm_data.addr, max_timeout=2)
            states.append(True if state and state == RunnerStates.STARTED else False)
        if any(states):
            self.pb_start.setEnabled(False)
            self.pb_tti_detect.setEnabled(False)
            self.pb_gnbbip_detect.setEnabled(False)
            self.pb_stop.setEnabled(True)

    def _error_during_detect(self, exc_tuple: tuple[Exception, str, str]) -> None:
        exc_type, exc_val, exc_tb = exc_tuple
        self.progress_bar.setValue(100)
        logger.warning(f"{exc_type.__class__.__name__}: {exc_val}")
        logger.debug(exc_tb)
        self._set_icons(button="pb_detect", icon_name="fa5s.times", color="red", spin=False)
        self._show_message_box(kind_of="warning", title="Warning", message="Testline/VMs configuration can be wrong")

