    def copy_logs_clicked(self):
        cp_from = path.join(self.le_store.text(), self.cb_copy_from.currentText())
        cp_to = self.le_copy_to.text()
        results = []
        file_list = tuple(walk(cp_from))[0][2]
        compress_type = self.cmb_compress.currentText()
        compress_ext = ["gz", "bz2", "xz", "zip", "bz"]
        if compress_type != "none" and not (
            len(file_list) == 1 and any(ext for ext in compress_ext if ext in file_list[0])
        ):
            cp_from = make_archive(base_name=cp_from, format=compress_type, root_dir=cp_from)
        if not path.isdir(cp_to):
            self._show_message_box("warning", "Directory not exists", f"Destination: {cp_to}")
        elif path.isfile(cp_from) and cp_to:
            logger.debug(f"Logs to copy: {cp_from}")
            results.append(copy_file(logger, cp_from, path.join(cp_to, cp_from.rpartition("/")[2])))
            remove(cp_from)
        elif path.isdir(cp_from) and cp_to:
            chdir(cp_from)
            logs2copy = glob(r"*.*")
            logger.debug(f"Logs to copy: {logs2copy}")
            for filelog in logs2copy:
                results.append(copy_file(logger, filelog, path.join(cp_to, filelog)))
        if all([results]):
            self._update_lc_statusbar(f"Logs were copied to {cp_to}")
        else:
            self._update_lc_statusbar(f"Problem: logs were not copied to {cp_to}")

    def _rotta_mount(self, directory: str) -> tuple[bool, str]:
        if self._is_rotta_mounted():
            return True, ""
        create_dir(directory)
        reason, ok_usr, ok_passwd, username, password = ("",) * 5
        username, ok_usr = QInputDialog.getText(self, "Username", "and press ENTER:", QLineEdit.Normal)
        if all([username, ok_usr]):
            password, ok_passwd = QInputDialog.getText(self, "Password", "and press ENTER:", QLineEdit.Password)
        if all([ok_usr, ok_passwd, username, password]):
            cmd = (
                "sudo mount //eseefsn50.emea.nsn-net.net/rotta4internal/LTE_2 {} "
                "-t cifs -o rw,norelatime,domain=NSN-INTRA,uid={},gid={},username={},"
                "password={}".format(directory, geteuid(), getegid(), username, password)
            )
            idx = cmd.rindex("=")
            logger.debug("cmd: {}={}".format(cmd[:idx], "*" * (len(cmd) - idx - 1)))
            stdout, stderr = Popen([cmd], shell=True, stderr=PIPE, stdout=PIPE).communicate()
            logger.debug(f'out:"{stdout}" err:"{stderr}"')
            reason = stderr if stderr else stdout
        if all([ok_usr, ok_passwd, username]) and not password:
            reason = "Wrong/empty password."
        return self._is_rotta_mounted(), reason

    def _is_rotta_mounted(self) -> bool:
        cmd = "mount -t cifs"
        #  lsblk --fs
        logger.debug(f"cmd: {cmd}")
        stdout, stderr = Popen([cmd], shell=True, stderr=PIPE, stdout=PIPE).communicate()
        logger.debug(f'out:"{stdout}" err:"{stderr}"')
        if "rotta4internal" in stdout.decode():
            return True
        stdout, stderr = Popen(["df -hT"], shell=True, stderr=PIPE, stdout=PIPE).communicate()
        logger.debug(f'out:"{stdout}" err:"{stderr}"')
        return False

    # <=><=><=><=><=><=><=><=><=><=><=> start/stop <=><=><=><=><=><=><=><=><=><=><=>
    def start_clicked(self):
        """Start collecting logs."""
        logger.info("Started")
        self.progress_bar.setValue(0)
        self._set_icons(button="pb_start", icon_name="fa5s.spinner", color="green", spin=True)
        self._update_lc_statusbar("Logcollector starting... Please wait!")
        self.run_in_background(
            job=self._start,
            signal_handlers={"finished": self._start_completed, "progress": self._progress_by_relative_value},
        )

    def _start(self, progress_callback):
        progress_callback.emit(10)
        self.log_dir_path, self.plugins_logs_path = create_dir_for_logs(logger, self.le_store.text())
        progress_callback.emit(10)
        vm_hosts = self._get_active_vms()
        builder = plugin_request.Builder("gui", self)
        progress_callback.emit(10)
        plugins = builder.build()
        progress_callback.emit(10)
        try:
            self._start_results = start_runners(logger, vm_hosts, self.plugins_logs_path, plugins)
        except Exception as e:
            logger.exception(e)
            self._show_message_box("critical", "Error", "Logcollector failed to start. Check logs for details.")
        progress_callback.emit(50)

    def check_action_results(self, action):
        results = getattr(self, f"_{action}_results")
        if any(start_result["status"] == StatusCode.ForbiddenStateTransition for start_result in results.values()):
            msg = f"Logcollector action {action.upper()} finished with failure."
            self.show_alert_for_error(results, action)
        else:
            msg = "Logcollector action {} finished with success. {}".format(
                action.upper(), f"Logs at: {self.log_dir_path}" if action == "stop" else ""
            )
        self._update_lc_statusbar(msg)

    def _update_lc_statusbar(self, msg):
        self.lc_statusbar.showMessage("{} | {}".format(datetime.strftime(datetime.now(), "%H:%M:%S"), msg))

    def _start_completed(self):
        self.check_action_results("start")
        self.pb_stop.setEnabled(True)
        self.pb_start.setEnabled(False)
        self.gb_vms.setEnabled(False)
        self.actionDisableSecurity.setEnabled(False)
        self._set_icons(button="pb_start", icon_name="fa5s.check", color="green", spin=False)
        self._set_icons(button="pb_stop", icon_name="fa5s.stop", color="red", spin=False)
        self.progress_bar.setValue(100)

    def show_alert_for_error(self, results, action):
        statuses = "\n".join(["{} | LC status: {}".format(ip, result["state"].name) for ip, result in results.items()])
        QMessageBox.warning(
            self,
            f"Failed to {action}",
            "Some servers failed to {}. Please reset servers and retry.\n" "{}".format(action, statuses),
            QMessageBox.Close,
            QMessageBox.Close,
        )

    def stop_clicked(self):
        """Stop collecting logs."""
        logger.info("Stopped")
        self.progress_bar.setValue(0)
        self._update_lc_statusbar("LogCollector stopping... Please wait!")
        self._set_icons(button="pb_stop", icon_name="fa5s.spinner", color="green", spin=True)
        self.run_in_background(
            job=self._stop,
            signal_handlers={"finished": self._stop_completed, "progress": self._progress_by_relative_value},
        )

    def _stop(self, progress_callback):
        progress_callback.emit(10)
        compression_type = self.cmb_compress.currentText()
        vm_hosts = self._get_active_vms()
        progress_callback.emit(20)
        self._stop_results = stop_runners(logger, vm_hosts)
        progress_callback.emit(20)
        if not self.plugins_logs_path and not self.log_dir_path:
            latest_logs_dir = get_latest_logs_directory(logger)
            if not latest_logs_dir:
                logger.warning("Logging was not started properly or logs are in unknown location. They are lost.")
                progress_callback.emit(10)
                return
            self.log_dir_path = path.join(self.le_store.text(), path.split(latest_logs_dir)[-1])
            self.plugins_logs_path = latest_logs_dir
        get_logs_from_runners(logger, vm_hosts, compression_type, self.plugins_logs_path, self.log_dir_path)
        progress_callback.emit(10)

    def _stop_completed(self):
        self.pb_stop.setEnabled(False)
        self.pb_start.setEnabled(True)
        self.check_action_results("stop")
        self.gb_vms.setEnabled(True)  # group box with VMs info
        self.actionDisableSecurity.setEnabled(True)
        self._set_icons(button="pb_stop", icon_name="fa5s.stop", color="red", spin=False)
        self._set_icons(button="pb_start", icon_name="fa5s.play", color="green", spin=False)
        self.progress_bar.setValue(100)
        self.le_store_edited()

    def _get_active_vms(self):
        vm_hosts = {}
        for vm_name, vm_data in self.vm_hosts.items():
            if getattr(self, f"cb_{vm_name}").isChecked():
                vm_hosts[vm_name] = vm_data
        return vm_hosts

