        bts_count = len(self.taf_tl_config.enbs or []) + len(self.taf_tl_config.gnbs or [])
        self.le_emss_ip.setText(get_emss_ip(cfg_dict["ip"]))
        for bts in filter(lambda x: x.startswith("bts_"), cfg_dict.keys()):
            bts_cb = getattr(self, "cb_emss_{}_vm{}".format(*bts.split("_")))
            bts_checked = cfg_dict[bts] and True if int(bts.split("_")[-1]) <= bts_count else False
            bts_cb.setChecked(bts_checked)

