    def _show_message_box(self, kind_of: str, title: str, message: str = "") -> None:
        """
        Generic method to show any QMessageBox delivered with Qt.

        :param kind_of: any of: information, question, warning, critical, about or aboutQt
        :param title: Title of modal window
        :param message: text of message, default is empty
        """
        message_box = getattr(QMessageBox, kind_of)
        if kind_of == "aboutQt":
            message_box(self, title)
        else:
            message_box(self, title, message)

    def run_in_background(self, job: Callable, signal_handlers: dict[str, Callable]) -> None:
        """
        Setup worker with signals callback to schedule GUI job in background.

        signal_handlers parameter is a dict with signals from  WorkerSignals,
        possibles signals are: finished, error, result, progress. Values in dict
        are methods/callables as handlers/callbacks for particular signal.

        :param job: GUI method to run in background
        :param signal_handlers: signals as keys: finished, error, result, progress and values as callable
        """
        worker = Worker(job)
        for signal, handler in signal_handlers.items():
            getattr(worker.signals, signal).connect(handler)
        if isinstance(job, partial):
            job_name = job.func.__name__
        else:
            job_name = job.__name__
        logger.debug(
            "Setup background job for: {} with {}".format(
                job_name, {signal: handler.__name__ for signal, handler in signal_handlers.items()}
            )
        )
        self.threadpool.start(worker)

    def _progress_by_abs_value(self, value: int) -> None:
        """
        Update progress bar by absolute value.

        :param value: absolute value of progress bar
        """
        self.progress_bar.setValue(value)

    def _progress_by_relative_value(self, percentage: int) -> None:
        """
        Update progress bar by relative percentage.

        :param percentage: value as percentage
        """
        reletive = (percentage / (self.progress_bar.maximum() - self.progress_bar.minimum())) * 100
        progress = int(self.progress_bar.value() + reletive)
        self.progress_bar.setValue(progress)

    @staticmethod
    def _fake_progress(progress_callback: Callable, done_event: Event, total_time: int, steps: int = 100) -> None:
        """
        Make fake progress for progressbar.

        :param progress_callback: function to update progress bar
        :param total_time: time for fill-up whole bar (in seconds)
        :param steps: number of steps (default 100)
        """
        for progress_step in range(1, steps + 1):
            if done_event.isSet():
                progress_callback.emit(100)
                break
            sleep(total_time / steps)
            progress_callback.emit(progress_step)

    def _set_icons(
        self, button: Optional[str] = None, icon_name: Optional[str] = None, color: str = "black", spin: bool = False
    ) -> None:
        """
        Universal method to set icon for QPushButtons.
        When button is provided without icon_name, current button icon will be removed.
        When none of button nor icon_name are provided, default starting icons are set for all buttons.

        :param button: button name
        :param icon_name: ex: spinner, check, times, pause
        :param color: ex: red, green, black
        :param spin: spinning icon: True or False
        """
        if not (button or icon_name):
            self.pb_detect.setIcon(qtawesome.icon("fa5s.search", color="blue"))
            self.pb_start.setIcon(qtawesome.icon("fa5s.play", color="green"))
            self.pb_stop.setIcon(qtawesome.icon("fa5s.stop", color="red"))
            self.pb_store.setIcon(qtawesome.icon("fa5s.file-download", color="blue"))
            self.pb_select_rotta.setIcon(qtawesome.icon("fa5s.folder-open", color="blue"))
            self.pb_copy_logs.setIcon(qtawesome.icon("fa5s.cloud-download-alt", color="blue"))
            self.pb_quit.setIcon(qtawesome.icon("fa5s.sign-out-alt", color="brown"))
            self.pb_load.setIcon(qtawesome.icon("fa5s.file-import", color="blue"))
            self.pb_save.setIcon(qtawesome.icon("fa5s.file-export", color="blue"))
            return
        btn = getattr(self, button)
        if spin and icon_name:
            icon = qtawesome.icon(f"{icon_name}", color=color, animation=qtawesome.Spin(btn, 2, 1))
        elif not spin and icon_name:
            icon = qtawesome.icon(f"{icon_name}", color=color)
        else:
            icon = QIcon()
        btn.setIcon(icon)

    def cb_toggled(self, plugin: str, requested_state: bool) -> None:
        """
        General method to toggle correct tab for particular plugin checkbox.

        :param plugin: plugin name
        :param requested_state: if True plugin tab will be enabled
        """
        if requested_state:
            self.tw_main.setTabEnabled(self._get_tab_index(plugin), True)
            self.plugins[plugin] = True
        else:
            if plugin == "tti_trace":
                for vm_id in range(1, MAX_SUPPORTED_VMs + 1):
                    getattr(self, f"tw_tti_{vm_id}").clear()
                self._set_icons(button="pb_tti_detect")
            self.tw_main.setTabEnabled(self._get_tab_index(plugin), False)
            self.plugins[plugin] = False

        self._cross_handling_emss_and_final_report_and_alarms(plugin)
        self._enable_disable_start_button()
        self.trigger_autosave()

    def _get_tab_index(self, plugin: str) -> int:
        """
        Search for tab index by plugin name.
        If not fount -1 is return

        :param plugin: plugin name
        :return: tab index at QTabWidget
        """
        for i in range(self.tw_main.count()):
            if plugin in self.tw_main.tabText(i).lower().replace(" ", "_"):
                return i
        return -1

    def _cross_handling_emss_and_final_report_and_alarms(self, plugin: str) -> None:
        """
        Handling Emss plugin tab when bts_info is toggled at final report plugin.

        :param plugin: plugin name
        """
        if plugin in ("emss", "final_report", "alarms"):
            if self.cb_alarms.isChecked() or (self.cb_final_report.isChecked() and self.cb_report_bts_info.isChecked()):
                self.tw_main.setTabEnabled(self._get_tab_index("emss"), True)
            else:
                if not self.cb_emss.isChecked():
                    self.tw_main.setTabEnabled(self._get_tab_index("emss"), False)

    def _enable_disable_start_button(self) -> None:
        """Check if at least one checkbox is checked and enable start button."""
        if any(getattr(self, f"cb_{plugin}").isChecked() for plugin in ALL_PLUGINS) and any(
            vmhost.alive for vmhost in self.vm_hosts.values()
        ):
            self.pb_start.setEnabled(True)
            self.pb_tti_detect.setEnabled(True)
        else:
            self.pb_start.setEnabled(False)
            self.pb_tti_detect.setEnabled(False)

    def cb_vm_toggled(self, vm: str, requested_state: bool) -> None:
        """
        Apply style to checkbox when it is checked and cleared when unchecked.
        Enable swconfig, syslog tabs and tti cell mapping detection when is checked.

        :param vm: VM label
        :param requested_state: if True VM checkbox will be checked
        """
        self.trigger_autosave()
        cb_vm_widget = getattr(self, f"cb_{vm}")
        if requested_state:
            cb_vm_widget.setStyleSheet(
                "QCheckBox {border: 1px solid gray; border-radius: 3px; background-color: orange; color: white;}"
            )
            self._enable_swconfig_tab(vm, True)
            self._enable_syslog_group(vm, True)
            self._enable_emss_bts_checkbox(vm, True)
        else:
            cb_vm_widget.setStyleSheet("QCheckBox {}")
            self._enable_swconfig_tab(vm, False)
            self._enable_syslog_group(vm, False)
            self._enable_emss_bts_checkbox(vm, False)
        self._toggled_vm_dependent_buttons()
        self.tab_swconfig_vm.setCurrentIndex(0)

    def _toggled_vm_dependent_buttons(self):
        if any(getattr(self, f"cb_{vm}").isChecked() for vm in vms_list):
            self.pb_check_servers.setEnabled(True)
        else:
            self.pb_check_servers.setEnabled(False)
            self.pb_start.setEnabled(False)
            self.pb_tti_detect.setEnabled(False)

