    @staticmethod
    def _run_file_dialog(for_load: bool, file_filter: str = "All Files [*.*](*.*)") -> str:
        """
        Handling open/save dialog windows to select file.

        :param for_load: if True show window for load, for save otherwise
        :param file_filter: list of types of files ;;-seperated: Text [*.txt](*.txt)
        :return: full path to file
        """
        if file_filter != "All Files [*.*](*.*)":
            file_filter = f"{file_filter};;All Files [*.*](*.*)"
        if for_load:
            conf_file = QFileDialog.getOpenFileName(
                QFileDialog(),
                caption="Open File",
                directory=environ["HOME"],
                filter=file_filter,
                options=QFileDialog.ReadOnly,
            )
        else:
            conf_file = QFileDialog.getSaveFileName(
                QFileDialog(),
                caption="Save File",
                directory=environ["HOME"],
                filter=file_filter,
                options=QFileDialog.ReadOnly,
            )
        return conf_file[0]

    @staticmethod
    def report_issue():
        """Open issue link in default web browser."""
        system("sensible-browser https://wrgitlab.ext.net.nokia.com/TAF/talib_mirgration/ta_logcollector/issues &")
